import { test, expect } from 'bun:test';
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { readUpload } from '../src/download.js';
function setup() {
  const root = mkdtempSync(join(tmpdir(), 'dl-'));
  mkdirSync(join(root, 'uploads', 'docs'), { recursive: true });
  writeFileSync(join(root, 'uploads', 'a.txt'), 'A');
  writeFileSync(join(root, 'uploads', 'docs', 'b.txt'), 'B');
  return join(root, 'uploads');
}
test('reads a file and a nested file', () => {
  const base = setup();
  expect(readUpload(base, 'a.txt').toString()).toBe('A');
  expect(readUpload(base, 'docs/b.txt').toString()).toBe('B');
});
test('missing file throws', () => expect(() => readUpload(setup(), 'zzz.txt')).toThrow());

