import { test, expect } from 'bun:test';
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { readUpload } from '../src/download.js';
function setup() {
  const root = mkdtempSync(join(tmpdir(), 'dl-'));
  mkdirSync(join(root, 'uploads'), { recursive: true });
  mkdirSync(join(root, 'uploads-evil'), { recursive: true });
  writeFileSync(join(root, 'uploads', 'a.txt'), 'A');
  writeFileSync(join(root, 'secret.txt'), 'SECRET');
  writeFileSync(join(root, 'uploads-evil', 'x.txt'), 'EVIL');
  return { base: join(root, 'uploads'), root };
}
test('parent traversal is refused', () => {
  const { base } = setup();
  expect(() => readUpload(base, '../secret.txt')).toThrow();
  expect(() => readUpload(base, 'docs/../../secret.txt')).toThrow();
});
test('a sibling directory sharing the prefix is refused', () => {
  const { base } = setup();
  expect(() => readUpload(base, '../uploads-evil/x.txt')).toThrow();
});
test('an absolute path is refused', () => {
  const { root, base } = setup();
  expect(() => readUpload(base, join(root, 'secret.txt'))).toThrow();
});
